    'doctor.msg.hook-activity.stale-unconfirmed.summary': 'session-summary hook 上次執行大約在 {hours} 小時前，而且過去 3 天也沒有任何 Claude Code 的寫入。如果這台機器已改用其他 agent（Codex / Gemini），這是正常的；如果你在這裡仍使用 Claude Code，擷取已經停了。',
    'doctor.msg.hook-activity.stale-unconfirmed.fix': '如果這台機器仍在使用 Claude Code：重啟它、結束一個 session，再執行一次 `memesh doctor`。若仍未恢復，執行 `memesh install-hooks`。',
