    'doctor.msg.hook-activity.stale-unknown.summary': '{hook} hook 的最後執行時間讀不出來（資料壞了，或是被時鐘不準的機器蓋的章）。擷取狀態現在是「不知道」，那跟「正常」不是同一件事。',
    'doctor.msg.hook-activity.stale-unknown.fix': '結束一次工作階段後再跑 `memesh doctor`——新的一次執行會把壞掉的時間蓋掉。',
