    'doctor.msg.hook-activity.disabled-env.summary': '自動擷取被這個 shell 環境中的 MEMESH_AUTO_CAPTURE=false 關閉了。doctor 只能看到自己所在的環境——如果你的 agent 執行時沒有這個變數，那邊的擷取不受影響。',
    'doctor.msg.hook-activity.not-wired.summary': '從來沒有任何擷取 hook 執行過——而且這台機器上沒有確認接好任何擷取 hook（Stop / PostToolUse / PreCompact），所以本來就沒有東西可以執行。',
    'doctor.msg.hook-activity.not-wired.fix': '想要自動擷取就執行 `memesh install-hooks`。如果這個安裝只走 MCP（Codex / Gemini），這是正常狀態，可以放心忽略。',
