    'doctor.msg.hook-activity.never-ran-legacy.summary': '沒有任何 hook 蓋過心跳章，但追蹤開始以來已存入 {captured} 筆自動擷取的記憶——很可能是心跳追蹤之前版本的 hook 還在執行。',
