    'doctor.msg.hook-activity.never-ran.summary': '从开始追踪到现在 {hours} 小时，没有任何抓取 hook 跑过——而 hook 接线是好的，代表它们该跑却没跑，没有任何东西被记下来。',
    'doctor.msg.hook-activity.never-ran.fix': '完整用一次工作会话，再跑 `memesh doctor`。如果还是说没有 hook 跑过，执行 `memesh install-hooks` 然后重启 agent。',
    'doctor.msg.hook-activity.stale.summary': '最后一次抓取 hook 是大约 {hours} 小时前跑的（{hook}）。如果你这段时间有在工作，代表抓取已经停了，那些会话的内容都没被存下来。',
    'doctor.msg.hook-activity.stale.fix': '重启 agent，结束一次工作会话，再跑 `memesh doctor`。如果没恢复，执行 `memesh install-hooks`。',
    'doctor.msg.hook-activity.stale-unconfirmed.summary': 'session-summary hook 上次运行大约在 {hours} 小时前，而且过去 3 天也没有任何 Claude Code 的写入。如果这台机器已改用其他 agent（Codex / Gemini），这是正常的；如果你在这里仍使用 Claude Code，捕获已经停了。',
    'doctor.msg.hook-activity.stale-unconfirmed.fix': '如果这台机器仍在使用 Claude Code：重启它、结束一个 session，再运行一次 `memesh doctor`。若仍未恢复，运行 `memesh install-hooks`。',
    'doctor.msg.hook-activity.query-failed.summary': '读不到 hook 活动记录：{detail}。抓取状态现在是「不知道」，那跟「正常」不是同一件事。',
    'doctor.msg.hook-activity.query-failed.fix': '用 `memesh doctor --verbose` 看完整错误，并确认 ~/.memesh 读得到、磁盘没满。',
    'doctor.msg.hook-activity.stale-unknown.summary': '{hook} hook 的最后执行时间读不出来（数据坏了，或是被时钟不准的机器盖的章）。抓取状态现在是「不知道」，那跟「正常」不是同一件事。',
    'doctor.msg.hook-activity.stale-unknown.fix': '结束一次工作会话后再跑 `memesh doctor`——新的一次执行会把坏掉的时间盖掉。',
    'doctor.msg.hook-activity.disabled.summary': '自动抓取已关闭（MEMESH_AUTO_CAPTURE 或配置文件的 autoCapture）——这是刻意设置，hook 没动静是预期中的。想恢复抓取就把它打开。',
    'doctor.msg.hook-activity.disabled-env.summary': '自动捕获被这个 shell 环境中的 MEMESH_AUTO_CAPTURE=false 关闭了。doctor 只能看到自己所在的环境——如果你的 agent 运行时没有这个变量，那边的捕获不受影响。',
    'doctor.msg.hook-activity.not-wired.summary': '从来没有任何捕获 hook 运行过——而且这台机器上没有确认接好任何捕获 hook（Stop / PostToolUse / PreCompact），所以本来就没有东西可以运行。',
    'doctor.msg.hook-activity.not-wired.fix': '想要自动抓取就执行 `memesh install-hooks`。如果这个安装只走 MCP（Codex / Gemini），这是正常状态，可以放心忽略。',
    'doctor.msg.hook-activity.stop-silent.summary': '{hook} hook 有在盖章，但从开始追踪到现在 {hours} 小时，session-summary hook 一次都没跑过——session 抓取可能坏了，只是被 commit 抓取盖住看不见。',
    'doctor.msg.hook-activity.stop-silent.fix': '完整结束一次工作会话再跑 `memesh doctor`。如果 session-summary 还是没跑过，执行 `memesh install-hooks` 然后重启 agent。',
    'doctor.msg.hook-activity.never-ran-legacy.summary': '没有任何 hook 盖过心跳章，但追踪开始以来已存入 {captured} 条自动捕获的记忆——很可能是心跳追踪之前版本的 hook 还在运行。',
    'doctor.msg.hook-activity.never-ran-legacy.fix': '把 memesh hooks 更新到当前版本（plugin 安装：`/plugin update memesh`；npm 安装：`memesh install-hooks`），然后重启 agent。',
