    'doctor.msg.hook-activity.never-ran.summary': 'Nenhum hook de captura foi executado nas {hours} horas desde que o acompanhamento começou, mesmo com a ligação dos hooks no lugar — nada está a ser guardado.',
    'doctor.msg.hook-activity.never-ran.fix': 'Termine uma sessão de trabalho e execute `memesh doctor` outra vez. Se continuar a dizer que nenhum hook correu, execute `memesh install-hooks` e reinicie o agente.',
    'doctor.msg.hook-activity.stale.summary': 'O último hook de captura correu há cerca de {hours} horas ({hook}). Se trabalhou desde então, a captura parou e nada dessas sessões foi guardado.',
    'doctor.msg.hook-activity.stale.fix': 'Reinicie o agente, termine uma sessão e execute `memesh doctor` outra vez. Se não recuperar, execute `memesh install-hooks`.',
    'doctor.msg.hook-activity.stale-unconfirmed.summary': 'O hook session-summary executou pela última vez há cerca de {hours} horas, e nenhuma escrita do Claude Code chegou nos últimos 3 dias. Se esta máquina passou a usar outro agente (Codex / Gemini), isto é esperado; se você ainda usa Claude Code aqui, a captura parou.',
    'doctor.msg.hook-activity.stale-unconfirmed.fix': 'Se você ainda usa Claude Code nesta máquina: reinicie-o, termine uma sessão e execute `memesh doctor` de novo. Se não recuperar, execute `memesh install-hooks`.',
    'doctor.msg.hook-activity.query-failed.summary': 'Não foi possível ler a atividade dos hooks na base de dados: {detail}. O estado da captura é desconhecido, o que não é o mesmo que saudável.',
    'doctor.msg.hook-activity.query-failed.fix': 'Execute `memesh doctor --verbose` para ver o erro completo e verifique que ~/.memesh é legível e que há espaço em disco.',
    'doctor.msg.hook-activity.stale-unknown.summary': 'O timestamp da última execução do hook {hook} não pode ser lido (corrompido, ou gravado por uma máquina com relógio errado). O estado da captura é "desconhecido", o que não é o mesmo que "saudável".',
    'doctor.msg.hook-activity.stale-unknown.fix': 'Termine uma sessão de trabalho e execute `memesh doctor` de novo — uma execução nova sobrescreve o timestamp inválido.',
    'doctor.msg.hook-activity.disabled.summary': 'A captura automática está desligada (MEMESH_AUTO_CAPTURE ou autoCapture na configuração) — deliberadamente, então o silêncio dos hooks é esperado. Reative para voltar a capturar sessões.',
    'doctor.msg.hook-activity.disabled-env.summary': 'A captura automática está desligada por MEMESH_AUTO_CAPTURE=false no ambiente deste shell. O doctor só enxerga o próprio ambiente — se o seu agente roda sem esta variável, a captura lá não é afetada.',
    'doctor.msg.hook-activity.not-wired.summary': 'Nenhum hook de captura jamais executou — e nenhum hook de captura (Stop / PostToolUse / PreCompact) está confirmado como ligado nesta máquina, então não há nada para executar.',
    'doctor.msg.hook-activity.not-wired.fix': 'Se quiser captura automática, execute `memesh install-hooks`. Se esta instalação é só MCP (Codex / Gemini), isto é esperado e pode ser ignorado.',
    'doctor.msg.hook-activity.stop-silent.summary': 'O hook {hook} está registando, mas o hook session-summary nunca executou nas {hours} horas desde que o rastreamento começou — a captura de sessões pode estar quebrada, escondida pela captura de commits.',
    'doctor.msg.hook-activity.stop-silent.fix': 'Termine uma sessão de trabalho e execute `memesh doctor` de novo. Se o session-summary continuar sem executar, execute `memesh install-hooks` e reinicie o agente.',
    'doctor.msg.hook-activity.never-ran-legacy.summary': 'Nenhum hook registou o heartbeat, mas {captured} memórias de captura automática chegaram desde que o rastreamento começou — hooks de uma versão anterior ao rastreamento provavelmente ainda estão a executar.',
    'doctor.msg.hook-activity.never-ran-legacy.fix': 'Atualize os hooks do memesh para a versão atual (plugin: `/plugin update memesh`; npm: `memesh install-hooks`) e reinicie o agente.',
