    'doctor.msg.update-status.deprecation-unknown.fix': 'Exécutez `memesh status` en ligne pour réessayer.',
    'doctor.msg.update-status.update-available.summary': 'Une version plus récente est disponible : {latest} (vous avez {current}).',
    'doctor.msg.update-status.update-available.fix': 'Exécutez `memesh update` pour mettre à jour.',
