    'doctor.msg.hook-wiring.entries-removed.summary': 'Die memesh-Einträge wurden aus {path} entfernt, die Verbindung ist deshalb unterbrochen.',
    'doctor.msg.hook-wiring.entries-removed.fix': 'Führen Sie `memesh install-hooks` erneut aus.',
    'doctor.msg.hook-wiring.root-moved.summary': 'Die Verbindung zeigt auf {path}, das es nicht mehr gibt (memesh wurde vermutlich verschoben).',
    'doctor.msg.hook-wiring.root-moved.fix': 'Führen Sie `memesh install-hooks` aus, um sie zu aktualisieren.',
    'doctor.msg.hook-activity.never-ran.summary': 'Seit Beginn der Aufzeichnung vor {hours} Stunden wurde kein Capture-Hook ausgeführt, obwohl die Hook-Verdrahtung vorhanden ist — nichts wird gespeichert.',
    'doctor.msg.hook-activity.never-ran.fix': 'Beenden Sie eine Arbeitssitzung und führen Sie `memesh doctor` erneut aus. Steht dort weiterhin, dass kein Hook lief, führen Sie `memesh install-hooks` aus und starten Sie den Agenten neu.',
    'doctor.msg.hook-activity.stale.summary': 'Der letzte Capture-Hook lief vor etwa {hours} Stunden ({hook}). Wenn Sie seitdem gearbeitet haben, ist die Erfassung gestoppt und nichts aus diesen Sitzungen wurde gespeichert.',
    'doctor.msg.hook-activity.stale.fix': 'Starten Sie den Agenten neu, beenden Sie eine Sitzung und führen Sie `memesh doctor` erneut aus. Erholt es sich nicht, führen Sie `memesh install-hooks` aus.',
    'doctor.msg.hook-activity.stale-unconfirmed.summary': 'Der session-summary-Hook lief zuletzt vor etwa {hours} Stunden, und in den letzten 3 Tagen kamen auch keine Claude-Code-Schreibvorgänge an. Ist diese Maschine zu einem anderen Agenten (Codex / Gemini) gewechselt, ist das erwartet; nutzen Sie hier noch Claude Code, ist die Erfassung gestoppt.',
    'doctor.msg.hook-activity.stale-unconfirmed.fix': 'Wenn Sie auf dieser Maschine noch Claude Code nutzen: neu starten, eine Sitzung beenden und `memesh doctor` erneut ausführen. Erholt es sich nicht, führen Sie `memesh install-hooks` aus.',
    'doctor.msg.hook-activity.query-failed.summary': 'Die Hook-Aktivität konnte nicht aus der Datenbank gelesen werden: {detail}. Der Zustand der Erfassung ist unbekannt, und das ist nicht dasselbe wie gesund.',
    'doctor.msg.hook-activity.query-failed.fix': 'Führen Sie `memesh doctor --verbose` für den vollständigen Fehler aus und prüfen Sie, ob ~/.memesh lesbar und die Festplatte nicht voll ist.',
    'doctor.msg.hook-activity.stale-unknown.summary': 'Der Zeitstempel des letzten Laufs des {hook}-Hooks ist unlesbar (beschädigt, oder von einer Maschine mit falscher Uhr geschrieben). Der Capture-Zustand ist „unbekannt", und das ist nicht dasselbe wie „gesund".',
    'doctor.msg.hook-activity.stale-unknown.fix': 'Beenden Sie eine Arbeitssitzung und führen Sie `memesh doctor` erneut aus — ein frischer Lauf überschreibt den defekten Zeitstempel.',
    'doctor.msg.hook-activity.disabled.summary': 'Die automatische Erfassung ist ausgeschaltet (MEMESH_AUTO_CAPTURE oder autoCapture in der Konfiguration) — absichtlich, daher ist die Stille der Hooks zu erwarten. Zum Fortsetzen wieder einschalten.',
    'doctor.msg.hook-activity.disabled-env.summary': 'Die automatische Erfassung ist durch MEMESH_AUTO_CAPTURE=false in der Umgebung dieser Shell ausgeschaltet. doctor sieht nur seine eigene Umgebung — läuft Ihr Agent ohne diese Variable, ist die Erfassung dort nicht betroffen.',
    'doctor.msg.hook-activity.not-wired.summary': 'Es ist noch nie ein Capture-Hook gelaufen — und auf dieser Maschine ist kein Capture-Hook (Stop / PostToolUse / PreCompact) nachweislich verdrahtet, es gibt also nichts auszuführen.',
    'doctor.msg.hook-activity.not-wired.fix': 'Für automatische Erfassung führen Sie `memesh install-hooks` aus. Bei einer reinen MCP-Installation (Codex / Gemini) ist das erwartet und kann ignoriert werden.',
    'doctor.msg.hook-activity.stop-silent.summary': 'Der {hook}-Hook stempelt, aber der session-summary-Hook ist in den {hours} Stunden seit Beginn der Aufzeichnung kein einziges Mal gelaufen — die Sitzungserfassung ist womöglich kaputt, verdeckt durch die Commit-Erfassung.',
    'doctor.msg.hook-activity.stop-silent.fix': 'Beenden Sie eine Arbeitssitzung und führen Sie `memesh doctor` erneut aus. Läuft session-summary dann immer noch nicht, führen Sie `memesh install-hooks` aus und starten Sie den Agenten neu.',
    'doctor.msg.hook-activity.never-ran-legacy.summary': 'Kein Hook hat den Heartbeat gestempelt, aber seit Beginn der Aufzeichnung sind {captured} automatisch erfasste Erinnerungen angekommen — Hooks aus einer Version vor dem Heartbeat-Tracking laufen wahrscheinlich noch.',
    'doctor.msg.hook-activity.never-ran-legacy.fix': 'Aktualisieren Sie die memesh-Hooks auf die aktuelle Version (Plugin: `/plugin update memesh`; npm: `memesh install-hooks`) und starten Sie den Agenten neu.',
    'doctor.msg.node-runtime.too-old.summary': 'Ihr Node.js ist älter, als dieses Paket unterstützt. {detail}',
    'doctor.msg.node-runtime.too-old.fix': 'Aktualisieren Sie Node.js auf {required} oder neuer und führen Sie `memesh doctor` erneut aus.',
    'doctor.msg.native-binding.node-too-old.summary': 'Das in dieser Node-Version eingebaute SQLite ist zu alt für memesh — es kann den Teil für die Suche nach Bedeutung nicht laden. Die vollständige Fassung kam mit Node 22.13.',
    'doctor.msg.native-binding.node-too-old.fix': 'Aktualisieren Sie Node auf 22.13 oder neuer und führen Sie `memesh doctor` erneut aus.',
    'doctor.msg.native-binding.not-installed.summary': 'sqlite-vec ist nicht installiert. Erinnerungen werden weiterhin gespeichert und über Stichwörter gefunden — nur die Suche nach Bedeutung ist aus.',
    'doctor.msg.native-binding.not-installed.fix': 'Führen Sie `npm install` in dem Ordner aus, der @pcircle/memesh verwendet.',
    'doctor.msg.native-binding.load-failed.summary': 'sqlite-vec konnte nicht geladen werden: {detail}. Die Suche nutzt nur noch Stichwörter.',
    'doctor.msg.native-binding.load-failed.fix': 'Ausführen: cd "{root}" && npm install --omit=dev',
    'doctor.msg.shell-cli.not-on-path.summary': 'Der Befehl `memesh` ist in Ihrem Terminal nicht verfügbar. Die Claude-Code-Funktionen laufen weiter — es betrifft nur das eigene Eintippen von `memesh`.',
    'doctor.msg.shell-cli.not-on-path.fix': 'Führen Sie `npm install -g @pcircle/memesh` aus, um ihn hinzuzufügen. Beide Installationen teilen sich dieselben Erinnerungen.',
