    'doctor.msg.hook-activity.never-ran.summary': 'Không có hook thu thập nào chạy trong {hours} giờ kể từ khi bắt đầu theo dõi, dù đấu nối hook vẫn ổn — không có gì được ghi nhớ.',
    'doctor.msg.hook-activity.never-ran.fix': 'Hoàn tất một phiên làm việc rồi chạy lại `memesh doctor`. Nếu vẫn báo chưa có hook nào chạy, chạy `memesh install-hooks` rồi khởi động lại agent.',
    'doctor.msg.hook-activity.stale.summary': 'Hook thu thập cuối cùng chạy khoảng {hours} giờ trước ({hook}). Nếu bạn đã làm việc kể từ đó, việc thu thập đã dừng và không có gì từ các phiên đó được lưu.',
    'doctor.msg.hook-activity.stale.fix': 'Khởi động lại agent, kết thúc một phiên rồi chạy lại `memesh doctor`. Nếu không khôi phục, chạy `memesh install-hooks`.',
    'doctor.msg.hook-activity.stale-unconfirmed.summary': 'Hook session-summary chạy lần cuối khoảng {hours} giờ trước, và 3 ngày qua cũng không có ghi nào từ Claude Code. Nếu máy này đã chuyển sang agent khác (Codex / Gemini), điều này là bình thường; nếu bạn vẫn dùng Claude Code ở đây, thu thập đã dừng.',
    'doctor.msg.hook-activity.stale-unconfirmed.fix': 'Nếu bạn vẫn dùng Claude Code trên máy này: khởi động lại, kết thúc một phiên rồi chạy lại `memesh doctor`. Nếu không hồi phục, chạy `memesh install-hooks`.',
    'doctor.msg.hook-activity.query-failed.summary': 'Không đọc được hoạt động hook từ cơ sở dữ liệu: {detail}. Tình trạng thu thập là không rõ, và điều đó không giống với bình thường.',
    'doctor.msg.hook-activity.query-failed.fix': 'Chạy `memesh doctor --verbose` để xem lỗi đầy đủ, và kiểm tra ~/.memesh đọc được và đĩa còn chỗ trống.',
    'doctor.msg.hook-activity.stale-unknown.summary': 'Không đọc được thời điểm chạy gần nhất của hook {hook} (dữ liệu hỏng, hoặc do một máy lệch đồng hồ ghi). Tình trạng thu thập hiện là "không rõ", và điều đó không giống "khỏe mạnh".',
    'doctor.msg.hook-activity.stale-unknown.fix': 'Kết thúc một phiên làm việc rồi chạy lại `memesh doctor` — lần chạy mới sẽ ghi đè dấu thời gian hỏng.',
    'doctor.msg.hook-activity.disabled.summary': 'Thu thập tự động đang tắt (MEMESH_AUTO_CAPTURE hoặc autoCapture trong cấu hình) — do chủ ý, nên hook im lặng là điều dự kiến. Bật lại để tiếp tục thu thập phiên.',
    'doctor.msg.hook-activity.disabled-env.summary': 'Thu thập tự động bị tắt bởi MEMESH_AUTO_CAPTURE=false trong môi trường shell này. doctor chỉ thấy được môi trường của chính nó — nếu agent của bạn chạy không có biến này, thu thập ở đó không bị ảnh hưởng.',
    'doctor.msg.hook-activity.not-wired.summary': 'Chưa có hook thu thập nào từng chạy — và trên máy này không xác nhận được hook thu thập nào (Stop / PostToolUse / PreCompact) đã đấu nối, nên không có gì để chạy.',
    'doctor.msg.hook-activity.not-wired.fix': 'Nếu muốn thu thập tự động, chạy `memesh install-hooks`. Nếu bản cài này chỉ dùng MCP (Codex / Gemini), đây là bình thường và có thể bỏ qua.',
    'doctor.msg.hook-activity.stop-silent.summary': 'Hook {hook} vẫn đang ghi dấu, nhưng hook session-summary chưa từng chạy lần nào trong {hours} giờ kể từ khi bắt đầu theo dõi — thu thập phiên có thể đã hỏng, bị che bởi thu thập commit.',
    'doctor.msg.hook-activity.stop-silent.fix': 'Kết thúc một phiên làm việc rồi chạy lại `memesh doctor`. Nếu session-summary vẫn chưa chạy, chạy `memesh install-hooks` và khởi động lại agent.',
    'doctor.msg.hook-activity.never-ran-legacy.summary': 'Chưa hook nào ghi dấu nhịp tim, nhưng từ khi bắt đầu theo dõi đã có {captured} ký ức thu thập tự động — nhiều khả năng hook từ phiên bản trước khi có theo dõi nhịp tim vẫn đang chạy.',
    'doctor.msg.hook-activity.never-ran-legacy.fix': 'Cập nhật hook memesh lên phiên bản hiện tại (plugin: `/plugin update memesh`; npm: `memesh install-hooks`), rồi khởi động lại agent.',
