    'doctor.msg.hook-wiring.no-marker.summary': 'memesh aún no está conectado con Claude Code, así que nada se recuerda automáticamente.',
    'doctor.msg.hook-wiring.no-marker.fix': 'Ejecuta `memesh install-hooks` una vez, y luego `memesh doctor` para confirmar.',
    'doctor.msg.hook-wiring.script-missing.summary': 'Un hook memesh conectado apunta a {path}, que ya no existe — el agente invoca un archivo inexistente en cada evento correspondiente. Suele ser residuo de una actualización que retiró el hook.',
    'doctor.msg.hook-wiring.script-missing.fix': 'Ejecuta `memesh install-hooks` para reconectar (elimina entradas retiradas) y reinicia el agente.',
    'doctor.msg.hook-wiring.marker-unreadable.summary': 'El registro de conexión en {path} no se puede leer.',
    'doctor.msg.hook-wiring.marker-unreadable.fix': 'Ejecuta `memesh install-hooks` otra vez.',
    'doctor.msg.hook-wiring.marker-malformed.summary': 'El registro de conexión está dañado.',
    'doctor.msg.hook-wiring.marker-malformed.fix': 'Ejecuta `memesh install-hooks` otra vez.',
    'doctor.msg.hook-wiring.settings-missing.summary': 'El archivo de ajustes de Claude Code ({path}) desapareció, así que la conexión está rota.',
    'doctor.msg.hook-wiring.settings-missing.fix': 'Ejecuta `memesh install-hooks` otra vez.',
    'doctor.msg.hook-wiring.settings-invalid.summary': '{path} está dañado (no es JSON válido).',
    'doctor.msg.hook-wiring.settings-invalid.fix': 'Restáuralo desde una copia de seguridad, o ejecuta `memesh install-hooks` para recrearlo.',
    'doctor.msg.hook-wiring.entries-removed.summary': 'Las entradas de memesh fueron eliminadas de {path}, así que la conexión está rota.',
    'doctor.msg.hook-wiring.entries-removed.fix': 'Ejecuta `memesh install-hooks` otra vez.',
    'doctor.msg.hook-wiring.root-moved.summary': 'La conexión apunta a {path}, que ya no existe (probablemente memesh se movió).',
    'doctor.msg.hook-wiring.root-moved.fix': 'Ejecuta `memesh install-hooks` para actualizarla.',
    'doctor.msg.hook-activity.never-ran.summary': 'Ningún hook de captura se ha ejecutado en las {hours} horas desde que empezó el seguimiento, aun con el cableado de hooks en su sitio — no se está guardando nada.',
    'doctor.msg.hook-activity.never-ran.fix': 'Termina una sesión de trabajo y vuelve a ejecutar `memesh doctor`. Si sigue diciendo que ningún hook se ejecutó, ejecuta `memesh install-hooks` y reinicia el agente.',
    'doctor.msg.hook-activity.stale.summary': 'El último hook de captura se ejecutó hace unas {hours} horas ({hook}). Si has trabajado desde entonces, la captura se detuvo y nada de esas sesiones se guardó.',
    'doctor.msg.hook-activity.stale.fix': 'Reinicia el agente, termina una sesión y vuelve a ejecutar `memesh doctor`. Si no se recupera, ejecuta `memesh install-hooks`.',
    'doctor.msg.hook-activity.stale-unconfirmed.summary': 'El hook session-summary se ejecutó por última vez hace unas {hours} horas, y tampoco llegó ninguna escritura de Claude Code en los últimos 3 días. Si esta máquina pasó a otro agente (Codex / Gemini), es lo esperado; si todavía usas Claude Code aquí, la captura se detuvo.',
    'doctor.msg.hook-activity.stale-unconfirmed.fix': 'Si todavía usas Claude Code en esta máquina: reinícialo, termina una sesión y vuelve a ejecutar `memesh doctor`. Si no se recupera, ejecuta `memesh install-hooks`.',
    'doctor.msg.hook-activity.query-failed.summary': 'No se pudo leer la actividad de los hooks en la base de datos: {detail}. El estado de la captura es desconocido, que no es lo mismo que sano.',
    'doctor.msg.hook-activity.query-failed.fix': 'Ejecuta `memesh doctor --verbose` para ver el error completo y comprueba que ~/.memesh se puede leer y que hay espacio en disco.',
    'doctor.msg.hook-activity.stale-unknown.summary': 'La marca de tiempo de la última ejecución del hook {hook} no se puede leer (corrupta, o escrita por una máquina con el reloj mal). El estado de la captura es «desconocido», que no es lo mismo que «sano».',
    'doctor.msg.hook-activity.stale-unknown.fix': 'Termina una sesión de trabajo y vuelve a ejecutar `memesh doctor` — una ejecución nueva sobrescribe la marca de tiempo dañada.',
    'doctor.msg.hook-activity.disabled.summary': 'La captura automática está desactivada (MEMESH_AUTO_CAPTURE o autoCapture en la configuración) — deliberadamente, así que el silencio de los hooks es lo esperado. Reactívala para volver a capturar sesiones.',
    'doctor.msg.hook-activity.disabled-env.summary': 'La captura automática está desactivada por MEMESH_AUTO_CAPTURE=false en el entorno de este shell. doctor solo ve su propio entorno — si tu agente corre sin esta variable, la captura allí no se ve afectada.',
    'doctor.msg.hook-activity.not-wired.summary': 'Ningún hook de captura se ha ejecutado nunca — y ningún hook de captura (Stop / PostToolUse / PreCompact) está confirmado como conectado en esta máquina, así que no hay nada que ejecutar.',
    'doctor.msg.hook-activity.not-wired.fix': 'Si quieres captura automática, ejecuta `memesh install-hooks`. Si esta instalación es solo MCP (Codex / Gemini), esto es lo esperado y puedes ignorarlo.',
    'doctor.msg.hook-activity.stop-silent.summary': 'El hook {hook} está sellando, pero el hook session-summary no se ha ejecutado ni una vez en las {hours} horas desde que empezó el seguimiento — la captura de sesiones puede estar rota, oculta tras la captura de commits.',
    'doctor.msg.hook-activity.stop-silent.fix': 'Termina una sesión de trabajo y vuelve a ejecutar `memesh doctor`. Si session-summary sigue sin ejecutarse, ejecuta `memesh install-hooks` y reinicia el agente.',
    'doctor.msg.hook-activity.never-ran-legacy.summary': 'Ningún hook ha sellado el latido, pero {captured} memorias de captura automática llegaron desde que empezó el seguimiento — probablemente siguen ejecutándose hooks de una versión anterior al seguimiento.',
    'doctor.msg.hook-activity.never-ran-legacy.fix': 'Actualiza los hooks de memesh a la versión actual (plugin: `/plugin update memesh`; npm: `memesh install-hooks`) y reinicia el agente.',
    'doctor.msg.node-runtime.too-old.summary': 'Tu Node.js es más antiguo de lo que este paquete admite. {detail}',
    'doctor.msg.node-runtime.too-old.fix': 'Actualiza Node.js a {required} o más nuevo, y luego ejecuta `memesh doctor` de nuevo.',
    'doctor.msg.native-binding.node-too-old.summary': 'El SQLite integrado en esta versión de Node es demasiado antiguo para memesh: no puede cargar la parte que busca por significado. La versión completa llegó en Node 22.13.',
    'doctor.msg.native-binding.node-too-old.fix': 'Actualiza Node a 22.13 o posterior y vuelve a ejecutar `memesh doctor`.',
    'doctor.msg.native-binding.not-installed.summary': 'sqlite-vec no está instalado. Los recuerdos se siguen guardando y encontrando por palabra clave — solo se apaga la búsqueda por significado.',
    'doctor.msg.native-binding.not-installed.fix': 'Ejecuta `npm install` en la carpeta que usa @pcircle/memesh.',
    'doctor.msg.native-binding.load-failed.summary': 'No se pudo cargar sqlite-vec: {detail}. La búsqueda vuelve a usar solo palabras clave.',
    'doctor.msg.native-binding.load-failed.fix': 'Ejecuta: cd "{root}" && npm install --omit=dev',
    'doctor.msg.shell-cli.not-on-path.summary': 'El comando `memesh` no está disponible en tu terminal. Las funciones de Claude Code siguen funcionando — esto solo afecta a escribir `memesh` tú mismo.',
    'doctor.msg.shell-cli.not-on-path.fix': 'Ejecuta `npm install -g @pcircle/memesh` para añadirlo. Ambas instalaciones comparten la misma memoria.',
